import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> menu = Arrays.asList("kopi susu", "teh", "es jeruk", "air", "coklat panas");

        List<String> hasil = menu.stream()
                .filter(m -> m.length() > 3)
                .map(m -> m.toUpperCase())
                .collect(Collectors.toList());
        System.out.println(hasil);

        List<Integer> panjang = menu.stream()
                .map(String::length)
                .collect(Collectors.toList());
        System.out.println(panjang);
    }
}

